#include "core/exploration_package.hpp"
#include "core/dialogue_catalogue.hpp"
#include "core/event_registry.hpp"
#include "core/holiday_scene.hpp"
#include "core/motion.hpp"
#include <iostream>
using namespace pet;
int main(){auto assets=std::filesystem::path("assets/original");auto p=loadExplorationPackage(assets/"exploration/dungeon-35/exploration.mdpe");auto c=loadDialogueCatalogue(assets/"gameplay/dialogue/catalogue.mdlc");auto m=loadEventRegistry(assets/"gameplay/events/contexts.mder");auto v=loadHolidayRegistry(assets/"gameplay/holiday");Explorer e(63504,42,p.assetVersion,p.floors,{}, {},p.expedition);e.enableGameplay(1000);e.enableCompanion();e.enableScreenExploration(200);e.enableHolidaySchedule();auto s=e.state();s.variety.schedule.destination=DayDestination::Exploration;s.variety.schedule.dungeon=35;e=Explorer(s);e.startGuildMorning(1000);bool shown=false;for(uint64_t now=1000;now<10000000;now+=250){auto cam=cameraFor(tilePoint(e.state().position),576,576,200);e.observeViewport(cam.x,cam.y);const auto before=e.state();auto& g=before.gameplay;ActorCompletion d;d.keyed=true;d.player=d.enemy=d.partner=now>=g.phaseStartedMs+600;for(auto& a:g.partyPlaybacks)if(now>=a.startedMs+600)d.actions.push_back({before.runId,a.round,a.id,before.floorIndex,a.actorId});auto u=e.advanceGameplay(now,d,c,&m,&v);if(before.floorIndex==14){if(!shown){shown=true;std::cout<<"MAP\n";for(int y=0;y<24;++y){for(int x=0;x<24;++x){int t=y*24+x;char ch=before.world.walkable(t)?'.':'#';if(t==before.position)ch='P';else if(t==g.companion.tile)ch='C';else for(auto& a:before.population.entities)if(a.tile==t)ch='0'+a.instanceId;std::cout<<ch;}std::cout<<'\n';}}if(!u.actors.empty() || u.event!=GameplayEvent::None){std::cout<<"t "<<now<<" life "<<unsigned(e.state().gameplay.life)<<" event "<<unsigned(u.event)<<" p "<<before.position<<" c "<<g.companion.tile<<" round "<<g.actionRound<<" hp "<<g.hearts<<"/"<<g.companion.hearts<<" intent "<<unsigned(g.companionIntent)<<" ctarget "<<g.companionTarget;for(auto& a:u.actors)std::cout<<" [actor "<<a.actorId<<" event "<<unsigned(a.event)<<" target "<<a.targetId<<" damage "<<a.damage<<"]";for(auto& a:e.state().population.entities)std::cout<<" E"<<a.instanceId<<":"<<a.tile<<":"<<a.remainingHits;std::cout<<'\n';}}if(e.state().gameplay.life==LifePhase::ReturnHome)break;}}
